def greet(name=None):
    if name is None:
        name = "stranger"
    return f"Hello, {name}"

print(greet())        # Hello, stranger
print(bool([]), bool([0]))  # False True

raw = input("Enter a number: ")
try:
    value = int(raw)
except ValueError:
    print("Not a whole number")
else:
    print(isinstance(value, int))  # True

def grade(score):
    if score >= 90:
        return "A"
    elif score >= 80:
        return "B"
    elif score >= 70:
        return "C"
    else:
        return "F"

attempts = 0
while attempts < 3:
    guess = input("Guess the number: ")
    if guess == "7":
        print("Correct!")
        break
    attempts += 1
else:
    print("Out of attempts")

