for number in range(2, 50):
    for divisor in range(2, number):
        if number % divisor == 0:
            break
    else:
        print(number, "is prime")

def rectangle_area(width, height):
    return width * height

def rectangle_perimeter(width, height):
    return 2 * (width + height)

print(rectangle_area(3, 4), rectangle_perimeter(3, 4))

def min_max(numbers):
    return min(numbers), max(numbers)

lowest, highest = min_max([4, 1, 9, 3])
print(lowest, highest)  # 1 9

def create_user(username, is_admin=False, active=True):
    return {"username": username, "is_admin": is_admin, "active": active}

create_user("ana")
create_user("bob", is_admin=True)
create_user(username="cleo", active=False, is_admin=False)

